import re
from dataclasses import dataclass, field
from typing import Optional

# "## [2.4.0] - 2024-05-02" or "## [Unreleased]" (no date).
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# A comment that ends its line takes the whitespace in front of it and after it
# with it, so no trailing whitespace is left behind.
END_OF_LINE_COMMENT = re.compile(r"[ \t]*<!--(?:(?!-->).)*-->[ \t]*(?=\r?\n|\Z)", re.DOTALL)
# Any other comment (inline, or spanning several lines) is removed as is.
COMMENT = re.compile(r"<!--(?:(?!-->).)*-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    text = END_OF_LINE_COMMENT.sub("", text)
    return COMMENT.sub("", text)


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                # Some other level-2 section: it does not belong to any release.
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def collapse_blank_lines(lines):
    result = []
    for line in lines:
        if line.strip() == "":
            if result and result[-1] == "":
                continue
            result.append("")
        else:
            result.append(line)
    while result and result[0] == "":
        result.pop(0)
    while result and result[-1] == "":
        result.pop()
    return result


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = "\n".join(collapse_blank_lines(release.body))
            if release.date is None:
                title = f"# {release.version}"
            else:
                title = f"# {release.version} ({release.date})"
            if body:
                return f"{title}\n\n{body}\n"
            return f"{title}\n"
    raise LookupError(version)

